const p = $input.first().json.prefijo;
if (!p || !String(p).startsWith('PRUEBA-8B-')) throw new Error('No hay datos de prueba pendientes. Corré scripts/preparar_prueba_8.8b.sql y volvé a ejecutar.');
return [{ json: { prefijo: p } }];

const p = $('CA88BP_Parametros').first().json.prefijo;
const a = $('CA88BP_Ejecutar_1').first().json, b = $('CA88BP_Ejecutar_2').first().json;
const sal = $('CA88BP_Ver_salidas').all().map(i => i.json).filter(x => x.reclamo_id);
const cola = $('CA88BP_Ver_cola').all().map(i => i.json).filter(x => x.documento_id);
const c = $('CA88BP_Ver_control').first().json;
const r1 = sal.find(x => x.reclamo_id === p + 'R1') || {}, r2 = sal.find(x => x.reclamo_id === p + 'R2') || {};
const g = k => cola.find(x => x.documento_id === p + k) || {};
const pf = ok => (ok ? 'PASA' : 'FALLA');
const t = (caso, ok, detalle) => ({ caso, resultado: pf(ok), detalle: typeof detalle === 'string' ? detalle : JSON.stringify(detalle) });
const res = [
  t('1 Primera pasada: 2 generadas, 5 derivadas, 0 con error', a.estado === 'procesado' && a.generadas === 2 && a.derivadas === 5 && a.con_error === 0 && a.ya_generadas === 0, { estado: a.estado, generadas: a.generadas, derivadas: a.derivadas, con_error: a.con_error, ya: a.ya_generadas }),
  t('2 Segunda pasada: sin pendientes (los derivados no se reintentan)', b.estado === 'sin pendientes' && b.generadas === 0 && b.derivadas === 0 && b.con_error === 0, { estado: b.estado, generadas: b.generadas, derivadas: b.derivadas, con_error: b.con_error }),
  t('3 R1: nombre real y link reemplazados, sin marcadores', r1.texto_final === 'Hola Ana Gómez, recibimos tu reclamo. Completá tus datos acá: https://formulario.cumbreandina.example/datos. Saludos. Ana Gómez', r1.texto_final || 'sin respuesta final'),
  t('4 R2: sin marcadores, solo el link', String(r2.texto_final || '').includes('formulario.cumbreandina.example') && !/\[[A-Z]+_\d+\]/.test(r2.texto_final || ''), r2.texto_final || 'sin respuesta final'),
  t('5 Solo hay 2 respuestas finales (R1 y R2); las demás no generaron nada', sal.length === 2 && sal.every(x => !/\[[A-Z_0-9]+\]/.test(x.texto_final)), sal.map(x => x.reclamo_id.replace(p, '')).join(',')),
  t('6 Cola: R4, R5, R6, R7 y R8 derivadas una sola vez; R4, R7 y R8 con prioridad alta', cola.length === 5 && ['R4','R5','R6','R7','R8'].every(k => g(k).documento_id) && String(g('R5').motivo).includes('[DNI_1]') && String(g('R6').motivo).startsWith('Marcador sin dato') && ['R4','R7','R8'].every(k => g(k).prioridad === 'alta'), cola.map(x => x.documento_id.replace(p, '') + ' (' + x.prioridad + '): ' + x.motivo)),
  t('7 Se registró un solo uso de dato real (el nombre de R1) y 2 auditorías sin el dato', c.reid === 1 && c.aud === 2 && c.aud_nombre === 0, c),
  t('8 Una sola fila de A13 en ejecuciones (la pasada con trabajo; la vacía no registra)', c.ejec === 1, { ejecuciones_A13: c.ejec }),
];
const pasan = res.filter(x => x.resultado === 'PASA').length;
return [{ json: { resumen: pasan + ' de ' + res.length + ' PASA', prefijo: p, pruebas: res } }];
